16	package io.github.microcks.service;
17	
18	import io.opentelemetry.api.common.AttributeKey;
19	import io.opentelemetry.sdk.trace.ReadableSpan;
20	import org.slf4j.Logger;
21	import org.slf4j.LoggerFactory;
22	import org.springframework.stereotype.Service;
23	
24	import java.util.ArrayList;
25	import java.util.Collections;
26	import java.util.LinkedHashMap;
27	import java.util.List;
28	import java.util.Map;
29	import java.util.Set;
30	
31	/**
32	 * Service for storing and retrieving OpenTelemetry spans organized by trace ID.
33	 */
34	@Service
35	public class SpanStorageService {
36	
37	   private static final Logger log = LoggerFactory.getLogger(SpanStorageService.class);
38	
39	   /**
40	    * Thread-safe LinkedHashMap storing lists of spans grouped by trace ID. LinkedHashMap maintains insertion order to
41	    * allow eviction. Key: trace ID (String), Value: List of spans for that trace
42	    */
43	   private final Map<String, List<ReadableSpan>> spansByTraceId = Collections.synchronizedMap(new LinkedHashMap<>());
44	
45	   /**
46	    * Maximum number of traces to keep in memory to prevent memory leaks. When this limit is exceeded, oldest traces are
47	    * removed.
48	    */
49	   private static final int MAX_TRACES = 1000;
50	
51	   /**
52	    * Maximum number of spans to keep per trace to prevent memory issues.
53	    */
54	   private static final int MAX_SPANS_PER_TRACE = 100;
55	
56	
57	   /**
58	    * Stores a span in the service, grouped by trace ID.
59	    *
60	    * @param span The span to store
61	    */
62	   public void storeSpan(ReadableSpan span) {
63	      String traceId = span.getSpanContext().getTraceId();
64	
65	      // Add the span to our collection
66	      spansByTraceId.computeIfAbsent(traceId, k -> new ArrayList<>()).add(span);
67	
68	      // Limit spans per trace to prevent memory issues
69	      List<ReadableSpan> spans = spansByTraceId.get(traceId);
70	      if (spans.size() > MAX_SPANS_PER_TRACE) {
71	         // Remove oldest span to cap memory
72	         spans.removeFirst();
73	      }
74	
75	      // Limit total number of traces to prevent memory leaks
76	      if (spansByTraceId.size() > MAX_TRACES) {
77	         // Remove oldest trace this works because LinkedHashMap maintains insertion order
78	         String oldestTraceId = spansByTraceId.keySet().iterator().next();
79	         spansByTraceId.remove(oldestTraceId);
80	      }
81	   }
82	
83	   /**
84	    * Retrieves all spans for a given trace ID.
85	    *
86	    * @param traceId The trace ID to look up
87	    * @return A list of spans for the given trace ID, or an empty list if no spans found
88	    */
89	   public List<ReadableSpan> getSpansForTrace(String traceId) {
90	      return spansByTraceId.getOrDefault(traceId, new ArrayList<>());
91	   }
92	
93	   /**
94	    * Clears all stored spans and traces from memory. Useful for testing or when you want to reset the service state.
95	    */
96	   public void clearAll() {
97	      log.info("Clearing all stored spans and traces from SpanStorageService");
98	      spansByTraceId.clear();
99	   }
100	
101	   /**
102	    * Retrieves trace IDs that have spans matching all specified attributes.
103	    *
104	    * @param requiredAttributes Map of attribute key -> expected value
105	    * @return A List of trace IDs that have spans matching all the provided attributes sorted by recency (most recent
106	    *         first)
107	    */
108	   public List<String> queryTraceIdsBySpanAttributes(Map<AttributeKey<?>, Object> requiredAttributes) {
109	      if (requiredAttributes == null || requiredAttributes.isEmpty()) {
110	         return new ArrayList<>(spansByTraceId.keySet());
111	      }
112	      return spansByTraceId.entrySet().stream()
113	            .filter(entry -> entry.getValue().stream()
114	                  .anyMatch(span -> requiredAttributes.entrySet().stream()
115	                        .allMatch(reqAttr -> valuesEqualAttr(span.toSpanData().getAttributes().get(reqAttr.getKey()),
116	                              reqAttr.getValue()))))
117	            .map(Map.Entry::getKey)
118	            // Sort by recency - most recent first
119	            .sorted((id1, id2) -> {
120	               List<ReadableSpan> spans1 = spansByTraceId.get(id1);
121	               List<ReadableSpan> spans2 = spansByTraceId.get(id2);
122	               if (spans1.isEmpty() || spans2.isEmpty())
123	                  return 0;
124	               long endTime1 = spans1.stream().mapToLong(s -> s.toSpanData().getEndEpochNanos()).max().orElse(0);
125	               long endTime2 = spans2.stream().mapToLong(s -> s.toSpanData().getEndEpochNanos()).max().orElse(0);
126	               return Long.compare(endTime2, endTime1); // Descending order
127	            }).toList();
128	   }
129	
130	
131	   public static boolean valuesEqualAttr(Object actual, Object expected) {
132	      if (actual == null && expected == null)
133	         return true;
134	      if (actual == null || expected == null)
135	         return false;
136	      if (actual.getClass().isAssignableFrom(expected.getClass())
137	            || expected.getClass().isAssignableFrom(actual.getClass())) {
138	         return actual.equals(expected);
139	      }
140	      // Fallback: compare string representations to allow comparing numbers to strings, etc.
141	      return String.valueOf(actual).equals(String.valueOf(expected));
142	   }
143	
144	   /**
145	    * Get all trace IDs currently stored.
146	    *
147	    * @return Set of trace IDs
148	    */
149	   public Set<String> getAllTraceIds() {
150	      return spansByTraceId.keySet();
151	   }
152	}
