45	/**
46	 * Test case for SpanStorageService class.
47	 */
48	class SpanStorageServiceTest {
49	
50	   private SpanStorageService spanStorageService;
51	
52	   @BeforeEach
53	   void setUp() {
54	      spanStorageService = new SpanStorageService();
55	   }
56	
57	   @Test
58	   @DisplayName("Should store and retrieve spans by trace ID")
59	   void shouldStoreAndRetrieveSpansByTraceId() {
60	      // Given
61	      String traceId = "trace-123";
62	      ReadableSpan span1 = createMockSpan(traceId, "span-1");
63	      ReadableSpan span2 = createMockSpan(traceId, "span-2");
64	
65	      // When
66	      spanStorageService.storeSpan(span1);
67	      spanStorageService.storeSpan(span2);
68	
69	      // Then
70	      List<ReadableSpan> retrievedSpans = spanStorageService.getSpansForTrace(traceId);
71	      assertEquals(2, retrievedSpans.size());
72	      assertTrue(retrievedSpans.contains(span1));
73	      assertTrue(retrievedSpans.contains(span2));
74	   }
75	
76	   @Test
77	   @DisplayName("Should return empty list for non-existent trace ID")
78	   void shouldReturnEmptyListForNonExistentTraceId() {
79	      // When
80	      List<ReadableSpan> spans = spanStorageService.getSpansForTrace("non-existent-trace");
81	
82	      // Then
83	      assertTrue(spans.isEmpty());
84	   }
85	
86	   @Test
87	   @DisplayName("Should limit spans per trace")
88	   void shouldLimitSpansPerTrace() {
89	      // Given
90	      String traceId = "trace-with-many-spans";
91	      int maxSpansPerTrace = 100; // From SpanStorageService.MAX_SPANS_PER_TRACE
92	
93	      // When - Add more spans than the limit
94	      for (int i = 0; i < maxSpansPerTrace + 10; i++) {
95	         ReadableSpan span = createMockSpan(traceId, "span-" + i);
96	         spanStorageService.storeSpan(span);
97	      }
98	
99	      // Then
100	      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(traceId);
101	      assertEquals(maxSpansPerTrace, spans.size());
102	   }
103	
104	   @Test
105	   @DisplayName("Should remove oldest traces when memory limit exceeded")
