package io.github.microcks.util.tracing;

import io.github.microcks.event.TraceEvent;

import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.sdk.trace.ReadableSpan;

import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Utility class providing helpers to filter and match tracing spans against subscription criteria. It is used to
 * decide whether a given {@link TraceEvent} matches the filter of a live trace subscriber.
 */
public final class SpanFilterUtil {

   /** Attribute key used to carry the service name on a span. */
   private static final AttributeKey<String> SERVICE_NAME_KEY = AttributeKey.stringKey("service.name");
   /** Attribute key used to carry the operation name on a span. */
   private static final AttributeKey<String> OPERATION_NAME_KEY = AttributeKey.stringKey("operation.name");
   /** Attribute key used to carry the client address on a span. */
   private static final AttributeKey<String> CLIENT_ADDRESS_KEY = AttributeKey.stringKey("client.address");

   /**
    * Private constructor to prevent instantiation of utility class.
    */
   private SpanFilterUtil() {
      throw new UnsupportedOperationException("Utility class cannot be instantiated");
   }

   /**
    * Checks whether a value matches a wildcard/regex pattern.
    *
    * @param pattern The pattern to match against. {@code *} matches any non-null value; otherwise the pattern is
    *                interpreted as a full regular expression, falling back to exact string equality if it is not a
    *                valid regex.
    * @param value   The value to test
    * @return true if the value matches the pattern
    */
   public static boolean matchesWildcard(String pattern, String value) {
      if (pattern == null && value == null) {
         return true;
      }
      if (pattern == null || value == null) {
         return false;
      }
      if ("*".equals(pattern)) {
         return true;
      }
      try {
         return Pattern.matches(pattern, value);
      } catch (PatternSyntaxException e) {
         // Not a valid regular expression, fall back to exact string equality.
         return pattern.equals(value);
      }
   }

   /**
    * Extracts a {@link TraceEvent} from a list of spans belonging to a single trace by reading the relevant span
    * attributes.
    *
    * @param traceId The trace ID the spans belong to
    * @param spans   The spans of the trace to inspect
    * @return A {@link TraceEvent} holding the extracted service, operation and client address (any of which may be
    *         null if the corresponding attribute is absent)
    */
   public static TraceEvent extractTraceEvent(String traceId, List<ReadableSpan> spans) {
      String service = null;
      String operation = null;
      String clientAddress = null;

      if (spans != null) {
         for (ReadableSpan span : spans) {
            if (service == null) {
               service = span.getAttribute(SERVICE_NAME_KEY);
            }
            if (operation == null) {
               operation = span.getAttribute(OPERATION_NAME_KEY);
            }
            if (clientAddress == null) {
               clientAddress = span.getAttribute(CLIENT_ADDRESS_KEY);
            }
         }
      }

      return new TraceEvent(traceId, service, operation, clientAddress);
   }

   /**
    * Checks whether a {@link TraceEvent} matches the provided filter patterns. Each field of the event is matched
    * against its respective pattern using {@link #matchesWildcard(String, String)}.
    *
    * @param event         The trace event to test
    * @param service       The service name pattern
    * @param operation     The operation name pattern
    * @param clientAddress The client address pattern
    * @return true if all three event fields match their respective patterns
    */
   public static boolean matchesTraceEvent(TraceEvent event, String service, String operation, String clientAddress) {
      return matchesWildcard(service, event.service()) && matchesWildcard(operation, event.operation())
            && matchesWildcard(clientAddress, event.clientAddress());
   }
}
