package io.github.microcks.web;

import io.github.microcks.event.TraceEvent;
import io.github.microcks.service.SpanStorageService;
import io.github.microcks.util.tracing.SpanFilterUtil;

import io.opentelemetry.sdk.trace.ReadableSpan;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Manages client subscriptions to live trace event streams. Clients register a {@link SseEmitter} together with a set
 * of filter criteria (service name, operation name and client address). Whenever new trace data becomes available, the
 * matching subscribers are notified through their emitter.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   /** Name used for the heartbeat SSE events. */
   private static final String HEARTBEAT_EVENT = "heartbeat";
   /** Name used for the trace update SSE events. */
   private static final String TRACE_EVENT = "trace";

   private final SpanStorageService spanStorageService;

   /** Set of active subscriptions. Backed by a concurrent set to allow safe iteration and mutation. */
   private final Set<Subscription> subscriptions = ConcurrentHashMap.newKeySet();

   /**
    * Creates a new TraceSubscriptionManager.
    *
    * @param spanStorageService The service used to retrieve spans for a given trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Registers a new subscription for a filtered live stream of trace events. An initial heartbeat event is sent to
    * the emitter immediately to confirm that the connection is established.
    *
    * @param emitter       The emitter to send trace events to
    * @param serviceName   Filter pattern for the service name (may be null)
    * @param operationName Filter pattern for the operation name (may be null)
    * @param clientAddress Filter pattern for the client address (may be null)
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      Subscription subscription = new Subscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> subscriptions.remove(subscription));
      emitter.onError(e -> subscriptions.remove(subscription));

      // Immediately send a heartbeat so the client knows the connection is alive.
      sendHeartbeat(subscription);
   }

   /**
    * Handles a {@link TraceEvent} by retrieving the spans of the related trace and forwarding the update to every
    * matching subscriber.
    *
    * @param event The trace event that has just been recorded
    */
   @EventListener
   public void onTraceUpdated(TraceEvent event) {
      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(event.traceId());
      if (spans == null || spans.isEmpty()) {
         // No spans stored for this trace yet, nothing to send.
         return;
      }

      TraceEvent enrichedEvent = SpanFilterUtil.extractTraceEvent(event.traceId(), spans);

      for (Subscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(enrichedEvent, subscription.serviceName, subscription.operationName,
               subscription.clientAddress)) {
            try {
               subscription.emitter.send(SseEmitter.event().name(TRACE_EVENT).data(enrichedEvent));
            } catch (IOException e) {
               log.debug("Failed to send trace event to subscriber, completing emitter: {}", e.getMessage());
               subscription.emitter.complete();
            }
         }
      }
   }

   /**
    * Sends a heartbeat SSE event to every registered emitter. This keeps idle connections alive and lets clients
    * detect dropped connections.
    */
   @Scheduled(fixedRate = 30000)
   public void sendHeartbeats() {
      for (Subscription subscription : subscriptions) {
         sendHeartbeat(subscription);
      }
   }

   /**
    * Sends a single heartbeat SSE event to the given subscription, completing its emitter if the send fails.
    *
    * @param subscription The subscription to send the heartbeat to
    */
   private void sendHeartbeat(Subscription subscription) {
      try {
         subscription.emitter.send(SseEmitter.event().name(HEARTBEAT_EVENT).data("ping"));
      } catch (IOException e) {
         log.debug("Failed to send heartbeat to subscriber, completing emitter: {}", e.getMessage());
         subscription.emitter.complete();
      }
   }

   /**
    * Holds an emitter together with the filter criteria of a subscription.
    */
   private static final class Subscription {
      private final SseEmitter emitter;
      private final String serviceName;
      private final String operationName;
      private final String clientAddress;

      private Subscription(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
         this.emitter = emitter;
         this.serviceName = serviceName;
         this.operationName = operationName;
         this.clientAddress = clientAddress;
      }
   }
}
